# Declarative additive tables only. All SQL syntax is generated by this installed
# runner; profiles contain identifiers, typed columns and a bounded check DSL.
Set-StrictMode -Version Latest

function Assert-K98TableIdentifier([string]$Value) {
    if($Value -cnotmatch '^[A-Za-z_][A-Za-z0-9_]{0,127}\z'){throw 'Ordinary table-profile identifier required'}
}
function Get-K98TableColumns($Values,$Columns) {
    if(@($Values).Count -lt 1 -or @($Values).Count -gt 16){throw 'Bounded nonempty key columns required'}
    $seen=@{};$quoted=@()
    foreach($name in $Values){
        Assert-K98TableIdentifier $name
        if(-not $Columns.ContainsKey($name) -or $seen.ContainsKey($name)){throw 'Unknown or repeated key column'}
        $seen[$name]=$true;$quoted+=('['+$name+']')
    }
    return ($quoted -join ',')
}
function Get-K98TableCheck($Expression,$Columns,[int]$Depth=0) {
    if($Depth -gt 3){throw 'Check expression depth exceeded'}
    if($Expression.op -ceq 'and') {
        Assert-K98ModuleFields $Expression @('op','args')
        if(@($Expression.args).Count -lt 2 -or @($Expression.args).Count -gt 8){throw 'Bounded conjunction required'}
        $parts=@($Expression.args|ForEach-Object {Get-K98TableCheck $_ $Columns ($Depth+1)})
        return ('('+($parts -join ' AND ')+')')
    }
    Assert-K98ModuleFields $Expression @('op','column','value')
    Assert-K98TableIdentifier $Expression.column
    if(-not $Columns.ContainsKey($Expression.column)){throw 'Unknown check column'}
    $column='['+$Expression.column+']';$value=$Expression.value
    switch -CaseSensitive ($Expression.op) {
        'eq' {
            if($value -isnot [string] -or $value -cnotmatch '^[\x20-\x7e]{0,128}\z'){throw 'Bounded ASCII literal required'}
            return ('('+ $column+"='"+$value.Replace("'","''")+"')")
        }
        'digits' {
            if($value -isnot [bool] -or -not $value){throw 'Explicit digit constraint required'}
            return ('('+ $column+" NOT LIKE '%[^0-9]%')")
        }
        'bytes_between' {
            if($value -isnot [array] -or $value.Count -ne 2 -or $value[0] -isnot [int] -or $value[1] -isnot [int] -or $value[0] -lt 0 -or $value[1] -lt $value[0] -or $value[1] -gt 1048576){throw 'Bounded byte interval required'}
            return ('(DATALENGTH('+ $column+') BETWEEN '+$value[0]+' AND '+$value[1]+')')
        }
        default {
            if($value -isnot [int] -or $value -lt 0 -or $value -gt 1048576){throw 'Bounded integer check value required'}
            switch -CaseSensitive ($Expression.op) {
                'gt' {return ('('+ $column+'>'+ $value+')')}
                'ge' {return ('('+ $column+'>='+ $value+')')}
                'bytes_eq' {return ('(DATALENGTH('+ $column+')='+ $value+')')}
                'bytes_max' {return ('(DATALENGTH('+ $column+')<='+ $value+')')}
                'bytes_min' {return ('(DATALENGTH('+ $column+')>='+ $value+')')}
                'json' {if($value -ne 1){throw 'JSON check value must be one'};return ('(ISJSON('+ $column+')=1)')}
                default {throw 'Unsupported table check operator'}
            }
        }
    }
}
function Read-K98TableProfile($Profile) {
    Assert-K98ModuleFields $Profile @('version','profile','migration_id','database_collation','tempdb_collation','compatibility_level','tables','requires')
    if($Profile.version -isnot [int] -or $Profile.version -ne 1 -or $Profile.profile -cne 'additive_tables_v1' -or
       $Profile.migration_id -cnotmatch '^[0-9]{8}_[0-9]{3}_[a-z0-9_]+\z'){throw 'Unsupported additive table profile'}
    if($Profile.database_collation -cnotmatch '^[A-Za-z0-9_]{1,128}\z' -or $Profile.tempdb_collation -cnotmatch '^[A-Za-z0-9_]{1,128}\z' -or $Profile.compatibility_level -notin @(130,140,150,160)){throw 'Exact SQL collation/compatibility required'}
    if(@($Profile.tables).Count -lt 1 -or @($Profile.tables).Count -gt 8 -or @($Profile.requires).Count -gt 64){throw 'Bounded additive table profile required'}
    foreach($r in $Profile.requires){
        Assert-K98ModuleFields $r @('migration_id','sha256','status')
        if($r.migration_id -cnotmatch '^[0-9]{8}_[0-9]{3}_[A-Za-z0-9_]+\z' -or $r.sha256 -cnotmatch '^[a-f0-9]{64}\z' -or $r.status -cnotin @('Applied','Failed')){throw 'Exact predecessor history required'}
    }
    $seen=@{};$constraints=@{};$built=@()
    foreach($t in $Profile.tables){
        Assert-K98ModuleFields $t @('schema','name','columns','primary_key','unique_keys','checks','foreign_keys')
        Assert-K98TableIdentifier $t.schema;Assert-K98TableIdentifier $t.name
        $key=$t.schema+'.'+$t.name
        if($seen.ContainsKey($key) -or $key -in @('dbo.SchemaMigrationHistory','dbo.DeploymentRunHistory')){throw 'Repeated or protected table'}
        if(@($t.columns).Count -lt 1 -or @($t.columns).Count -gt 64 -or @($t.unique_keys).Count -gt 8 -or @($t.checks).Count -gt 16 -or @($t.foreign_keys).Count -gt 8){throw 'Table structure exceeds bound'}
        $columns=@{};$parts=@()
        foreach($c in $t.columns){
            Assert-K98ModuleFields $c @('name','type','nullable','collation')
            Assert-K98TableIdentifier $c.name
            if($columns.ContainsKey($c.name) -or $c.nullable -isnot [bool]){throw 'Repeated column or invalid nullability'}
            $type=[string]$c.type
            if($type -cnotmatch '^(int|bigint|bit|uniqueidentifier|date|datetime2\([0-7]\)|binary\([1-9][0-9]{0,2}\)|varchar\([1-9][0-9]{0,2}\)|nvarchar\((?:[1-9][0-9]{0,2}|max)\))\z'){throw 'Unsupported ordinary column type'}
            $text='['+$c.name+'] '+$type
            if($type -cmatch '^(n?varchar)\('){
                if($c.collation -isnot [string] -or $c.collation -cnotmatch '^[A-Za-z0-9_]{1,128}\z'){throw 'Explicit character collation required'}
                $text+=' COLLATE '+$c.collation
            }elseif($null -ne $c.collation){throw 'Non-character collation refused'}
            $text+= $(if($c.nullable){' NULL'}else{' NOT NULL'})
            $columns[$c.name]=$c;$parts+=$text
        }
        if($t.primary_key -isnot [pscustomobject]){throw 'Exactly one primary key object required'}
        foreach($k in @($t.primary_key)+@($t.unique_keys)){
            Assert-K98ModuleFields $k @('name','columns');Assert-K98TableIdentifier $k.name
            $constraint=$t.schema+'.'+$k.name
            if($constraints.ContainsKey($constraint)){throw 'Repeated constraint name'};$constraints[$constraint]=$true
            $list=Get-K98TableColumns $k.columns $columns
            $primary=$k -eq $t.primary_key
            foreach($name in $k.columns){if($columns[$name].type -like '*(max)' -or ($primary -and $columns[$name].nullable)){throw 'Unsupported key column'} }
            $parts+=('CONSTRAINT ['+$k.name+'] '+$(if($primary){'PRIMARY KEY CLUSTERED'}else{'UNIQUE NONCLUSTERED'})+' ('+$list+')')
        }
        foreach($check in $t.checks){
            Assert-K98ModuleFields $check @('name','expression');Assert-K98TableIdentifier $check.name
            $constraint=$t.schema+'.'+$check.name
            if($constraints.ContainsKey($constraint)){throw 'Repeated constraint name'};$constraints[$constraint]=$true
            $parts+=('CONSTRAINT ['+$check.name+'] CHECK '+(Get-K98TableCheck $check.expression $columns))
        }
        $foreign=@()
        foreach($f in $t.foreign_keys){
            Assert-K98ModuleFields $f @('name','columns','schema','table','target_columns')
            foreach($name in @($f.name,$f.schema,$f.table)){Assert-K98TableIdentifier $name}
            $constraint=$t.schema+'.'+$f.name
            if($constraints.ContainsKey($constraint)){throw 'Repeated constraint name'};$constraints[$constraint]=$true
            $list=Get-K98TableColumns $f.columns $columns
            $targetNames=@{};foreach($name in $f.target_columns){Assert-K98TableIdentifier $name;if($targetNames.ContainsKey($name)){throw 'Repeated reference column'};$targetNames[$name]=$true}
            if(@($f.columns).Count -ne @($f.target_columns).Count){throw 'Reference key arity differs'}
            $target=$f.schema+'.'+$f.table
            # New dependencies must precede their consumers; no cycles/self refs.
            foreach($candidate in $Profile.tables){if(($candidate.schema+'.'+$candidate.name) -ieq $target -and -not $seen.ContainsKey($target)){throw 'New referenced table must precede its consumer'}}
            if($seen.ContainsKey($target)){
                $parent=$seen[$target];$matches=$false
                foreach($keySpec in @($parent.primary_key)+@($parent.unique_keys)){
                    if((@($keySpec.columns) -join ',') -ceq (@($f.target_columns) -join ',')){$matches=$true}
                }
                if(-not $matches){throw ('Referenced unique key missing in profile: '+$target)}
            }
            $targetList=(@($f.target_columns|ForEach-Object {'['+$_+']'}) -join ',')
            $foreign+=('CONSTRAINT ['+$f.name+'] FOREIGN KEY ('+$list+') REFERENCES ['+$f.schema+'].['+$f.table+'] ('+$targetList+')')
        }
        $built+=@{Table=$t;Body=($parts -join ',');Create=('CREATE TABLE ['+$t.schema+'].['+$t.name+'] ('+(@($parts)+@($foreign) -join ',')+');')}
        $seen[$key]=$t
    }
    return @{Profile=$Profile;Tables=$built;Texts=@{}}
}

function Get-K98TableImageSql([string]$Catalog,[string]$Id) {
    # Both arguments are fixed runner syntax, not supplied by the profile.
    return @"
SELECT (SELECT c.column_id,c.name,c.system_type_id,c.max_length,c.precision,c.scale,c.collation_name,c.is_nullable,c.is_identity,c.is_computed,c.is_rowguidcol,c.is_sparse,c.generated_always_type,c.is_filestream
 FROM $Catalog.sys.columns c WHERE c.object_id=$Id ORDER BY c.column_id FOR JSON PATH) AS columns_json,
 (SELECT i.name,i.type,i.is_unique,i.is_primary_key,i.is_unique_constraint,i.is_disabled,i.ignore_dup_key,i.has_filter,i.filter_definition,i.is_hypothetical,
 JSON_QUERY((SELECT ic.index_column_id,ic.column_id,ic.key_ordinal,ic.is_descending_key,ic.is_included_column FROM $Catalog.sys.index_columns ic WHERE ic.object_id=i.object_id AND ic.index_id=i.index_id ORDER BY ic.index_column_id FOR JSON PATH)) AS key_columns
 FROM $Catalog.sys.indexes i WHERE i.object_id=$Id ORDER BY i.name COLLATE Latin1_General_100_BIN2 FOR JSON PATH) AS indexes_json,
 (SELECT c.name,c.definition,c.is_disabled,c.is_not_trusted,c.is_not_for_replication FROM $Catalog.sys.check_constraints c WHERE c.parent_object_id=$Id ORDER BY c.name COLLATE Latin1_General_100_BIN2 FOR JSON PATH) AS checks_json
 FOR JSON PATH,WITHOUT_ARRAY_WRAPPER
"@
}
function Assert-K98TableImages($Connection,$Transaction,$Loaded,[bool]$After) {
    $all=@{};foreach($built in $Loaded.Tables){$all[$built.Table.schema+'.'+$built.Table.name]=$true}
    foreach($built in $Loaded.Tables){
        $t=$built.Table;$key=$t.schema+'.'+$t.name
        $null=Invoke-K98ModuleQuery $Connection $Transaction "IF SCHEMA_ID(@schema) IS NULL THROW 51950,'Existing schema required.',1;" @{schema=$t.schema}
        if(-not $After){
            $null=Invoke-K98ModuleQuery $Connection $Transaction "IF OBJECT_ID(@name) IS NOT NULL THROW 51950,'Additive preimage must be absent; do not adopt existing tables without a matching receipt.',1;" @{name=$key}
            foreach($constraint in @($t.primary_key)+@($t.unique_keys)+@($t.checks)+@($t.foreign_keys)){
                $null=Invoke-K98ModuleQuery $Connection $Transaction "IF EXISTS(SELECT 1 FROM sys.objects WHERE schema_id=SCHEMA_ID(@schema) AND name=@constraint) THROW 51950,'Additive constraint name already exists.',1;" @{schema=$t.schema;constraint=$constraint.name}
            }
            $null=Invoke-K98ModuleQuery $Connection $Transaction ('CREATE TABLE #K98_TableExpected ('+$built.Body+'); DROP TABLE #K98_TableExpected;')
        }else{
            # Do not use the migration as its own outcome probe. Generate a
            # temporary expected table and compare complete structural metadata.
            $expected=Get-K98TableImageSql 'tempdb' "OBJECT_ID(N'tempdb..#K98_TableExpected')"
            $actual=Get-K98TableImageSql 'DB_NAME_UNUSED' 'OBJECT_ID(@name)'
            $actual=$actual.Replace('DB_NAME_UNUSED.sys.','sys.')
            $query="CREATE TABLE #K98_TableExpected ("+$built.Body+");`n"+@"
IF OBJECT_ID(@name,N'U') IS NULL THROW 51950,'Additive postimage table missing.',1;
IF OBJECT_NAME(OBJECT_ID(@name)) COLLATE Latin1_General_100_BIN2<>@table COLLATE Latin1_General_100_BIN2
 OR OBJECT_SCHEMA_NAME(OBJECT_ID(@name)) COLLATE Latin1_General_100_BIN2<>@schema COLLATE Latin1_General_100_BIN2
 THROW 51950,'Additive object identity differs.',1;
IF EXISTS(SELECT 1 FROM sys.columns WHERE object_id=OBJECT_ID(@name) AND user_type_id<>system_type_id)
 OR EXISTS(SELECT 1 FROM sys.tables WHERE object_id=OBJECT_ID(@name) AND (temporal_type<>0 OR is_memory_optimized<>0 OR is_filetable<>0 OR is_replicated<>0 OR is_merge_published<>0 OR is_sync_tran_subscribed<>0 OR is_tracked_by_cdc<>0 OR filestream_data_space_id<>0))
 OR EXISTS(SELECT 1 FROM sys.triggers WHERE parent_id=OBJECT_ID(@name))
 OR EXISTS(SELECT 1 FROM sys.default_constraints WHERE parent_object_id=OBJECT_ID(@name))
 OR EXISTS(SELECT 1 FROM sys.partitions WHERE object_id=OBJECT_ID(@name) AND (data_compression<>0 OR partition_number<>1))
 OR EXISTS(SELECT 1 FROM sys.indexes i JOIN sys.data_spaces d ON d.data_space_id=i.data_space_id WHERE i.object_id=OBJECT_ID(@name) AND d.type<>'FG')
 THROW 51950,'Unsupported additive table metadata.',1;
SELECT ($expected) AS expected_image,($actual) AS actual_image;
DROP TABLE #K98_TableExpected;
"@
            $rows=Invoke-K98ModuleQuery $Connection $Transaction $query @{name=$key;table=$t.name;schema=$t.schema}
            if($rows.Count -ne 1 -or $rows[0].actual_image -cne $rows[0].expected_image){throw ('Additive table shape differs: '+$key)}
        }
        $expectedRows=@()
        foreach($f in $t.foreign_keys){
            $target=$f.schema+'.'+$f.table
            if($After -or -not $all.ContainsKey($target)){
                $keys=Invoke-K98ModuleQuery $Connection $Transaction @'
SELECT i.index_id,c.name,ic.key_ordinal FROM sys.indexes i
JOIN sys.index_columns ic ON ic.object_id=i.object_id AND ic.index_id=i.index_id
JOIN sys.columns c ON c.object_id=ic.object_id AND c.column_id=ic.column_id
WHERE i.object_id=OBJECT_ID(@name,N'U') AND i.is_unique=1 AND i.is_disabled=0 AND i.has_filter=0 AND ic.key_ordinal>0 ORDER BY i.index_id,ic.key_ordinal;
'@ @{name=$target}
                $match=$false
                foreach($group in ($keys|Group-Object index_id)) {if((@($group.Group.name) -join ',') -ceq (@($f.target_columns) -join ',')){$match=$true}}
                if(-not $match){throw ('Referenced unique key missing: '+$target)}
            }
            for($i=0;$i -lt @($f.columns).Count;$i++){
                $expectedRows+=($f.name+'|'+($i+1)+'|'+$f.columns[$i]+'|'+$target+'|'+$f.target_columns[$i]+'|0|0|0|0|0')
            }
        }
        if($After){
            $rows=Invoke-K98ModuleQuery $Connection $Transaction @'
SELECT f.name,fc.constraint_column_id AS ordinal,pc.name AS parent_column,
OBJECT_SCHEMA_NAME(f.referenced_object_id)+'.'+OBJECT_NAME(f.referenced_object_id) AS target,rc.name AS target_column,
CONVERT(int,f.is_disabled) AS disabled,CONVERT(int,f.is_not_trusted) AS untrusted,CONVERT(int,f.is_not_for_replication) AS [replication],f.delete_referential_action AS deletes,f.update_referential_action AS updates
FROM sys.foreign_keys f JOIN sys.foreign_key_columns fc ON fc.constraint_object_id=f.object_id
JOIN sys.columns pc ON pc.object_id=fc.parent_object_id AND pc.column_id=fc.parent_column_id
JOIN sys.columns rc ON rc.object_id=fc.referenced_object_id AND rc.column_id=fc.referenced_column_id
WHERE f.parent_object_id=OBJECT_ID(@name);
'@ @{name=$key}
            $actualRows=@($rows|ForEach-Object {$_.name+'|'+$_.ordinal+'|'+$_.parent_column+'|'+$_.target+'|'+$_.target_column+'|'+$_.disabled+'|'+$_.untrusted+'|'+$_.replication+'|'+$_.deletes+'|'+$_.updates})
            if((@($expectedRows|Sort-Object) -join "`n") -cne (@($actualRows|Sort-Object) -join "`n")){throw ('Additive foreign key shape differs: '+$key)}
        }
    }
}
